-- The two checklists published on 2026-10-25: Noticing What Went Right Today
-- (Gratitude) and When Everything Is Too Loud (Overstimulation).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-25`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('noticing-what-went-right-today', 'Noticing What Went Right Today', 'For the end of a day that felt like nothing good happened. It asks for three small things rather than big ones, what it was about them that landed, and one person to actually thank, in two minutes at the same point each day.', 'Gratitude', '["Write down three small things, not big ones — the coffee and the bus are the right size.", "Say what it was about them that landed — “the quiet” tells you more than “the walk”.", "Do it at the same point each day — a habit needs a hook more than it needs willpower.", "Include something you did, not only got — credit is harder to give yourself and worth more.", "Name one person who helped and tell them — thanks said out loud does twice the work.", "Keep it to two minutes — a long entry is why people stop by Thursday.", "Let a bad day have a short list — one thing counts on the days one is all there is.", "Read last week''s back on a flat day — your own handwriting argues better than advice does."]'::jsonb, 'daily', array['Mindfulness', 'Self-Compassion']::text[], 1, '2026-10-25T16:00:00+00:00'::timestamptz),
  ('when-everything-is-too-loud', 'When Everything Is Too Loud', 'For the point in a day when the noise, the light and the people are more than you can take. It cuts one input at a time, gets the ears and the lights down, asks the room for ten minutes, and returns you to one job rather than the list.', 'Overstimulation', '["Cut one input before you fix anything — the radio off is faster than tidying the room.", "Put something over your ears for ten minutes — earplugs, or headphones with nothing playing.", "Turn the overhead light down to one lamp — bright light carries more than people notice.", "Get the tag, the waistband or the shoes off — the body cannot hear you over an itch.", "Go to the smallest room in the house — less space often means less coming at you.", "Say out loud that you need ten minutes — nobody can read this from the outside.", "Put one hand on something cool — a sink, a wall, a glass; one steady signal helps.", "Come back to one thing, not the list — the room can stay noisy while you do one job."]'::jsonb, 'as needed', array['Grounding', 'Stress']::text[], 1, '2026-10-25T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
